#!/usr/bin/env python3
"""Turn design/tokens.json into the Swift token table.

    python3 -I scripts/gen_tokens.py

Writes ios/Openband/UI/Design/Tokens.generated.swift. Views never read this table directly;
they use the semantic API in Tokens.swift, Typography.swift and Motion.swift.
"""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "design" / "tokens.json"
TARGET = ROOT / "ios" / "Openband" / "UI" / "Design" / "Tokens.generated.swift"

HEADER = """\
// Generated by scripts/gen_tokens.py from design/tokens.json. Do not edit; run `python3 -I scripts/gen_tokens.py`.
// swiftlint:disable all
import CoreGraphics
import SwiftUI

/// Raw design-token tables. Views use the semantic API in Tokens.swift, Typography.swift and Motion.swift.
enum FBTokenTable {
    struct ColorEntry: Hashable, Sendable {
        let name: String
        let light: UInt32
        let dark: UInt32
        let lightContrast: UInt32
        let darkContrast: UInt32
    }

    struct TypeEntry: Sendable {
        let name: String
        let size: CGFloat
        let lineHeight: CGFloat
        /// 400, 500 or 600; Bold Text steps each one up.
        let weight: Int
        let relativeTo: Font.TextStyle
        let isFigure: Bool
        /// Technical readouts (timer, pace, splits) are set in the mono face.
        let isMono: Bool
    }

    struct MotionEntry: Sendable {
        let c0x: Double
        let c0y: Double
        let c1x: Double
        let c1y: Double
        let duration: Double
    }
"""


def number(value: float) -> str:
    return str(int(value)) if float(value) == int(value) else str(value)


def scalar_block(name: str, values: dict[str, float], indent: str = "    ") -> str:
    lines = [f"{indent}enum {name} {{"]
    for key, value in values.items():
        lines.append(f"{indent}    static let {key}: CGFloat = {number(value)}")
    lines.append("")
    lines.append(f"{indent}    static let all: [(name: String, value: CGFloat)] = [")
    for key in values:
        lines.append(f'{indent}        ("{key}", {key}),')
    lines.append(f"{indent}    ]")
    lines.append(f"{indent}}}")
    return "\n".join(lines)


def main() -> None:
    tokens = json.loads(SOURCE.read_text())
    out: list[str] = [HEADER]

    out.append("\n    enum Colors {")
    for name, entry in tokens["colors"].items():
        light = entry["light"]
        dark = entry["dark"]
        out.append(
            f'        static let {name} = ColorEntry(name: "{name}", light: 0x{light}, dark: 0x{dark},'
            f' lightContrast: 0x{entry.get("lightContrast", light)}, darkContrast: 0x{entry.get("darkContrast", dark)})'
        )
    out.append("")
    out.append("        static let all: [ColorEntry] = [")
    out.extend(f"            {name}," for name in tokens["colors"])
    out.append("        ]")
    out.append("    }\n")

    for swift_name, key in (("Space", "space"), ("Radius", "radius"), ("Stroke", "stroke"), ("Size", "size")):
        out.append(scalar_block(swift_name, tokens[key]))
        out.append("")

    out.append("    enum TypeScale {")
    for name, entry in tokens["type"].items():
        out.append(
            f'        static let {name} = TypeEntry(name: "{name}", size: {number(entry["size"])},'
            f' lineHeight: {number(entry["lineHeight"])}, weight: {entry["weight"]},'
            f' relativeTo: .{entry["relativeTo"]}, isFigure: {str(entry.get("figure", False)).lower()},'
            f' isMono: {str(entry.get("mono", False)).lower()})'
        )
    out.append("    }\n")

    fonts = tokens["fonts"]
    out.append("    enum FontName {")
    for key, value in fonts.items():
        out.append(f'        static let {key} = "{value}"')
    out.append("    }\n")

    out.append("    enum Motion {")
    for name, entry in tokens["motion"].items():
        c = entry["curve"]
        out.append(
            f"        static let {name} = MotionEntry(c0x: {c[0]}, c0y: {c[1]}, c1x: {c[2]}, c1y: {c[3]},"
            f" duration: {entry['duration']})"
        )
    out.append("    }\n")

    out.append("    enum Bands {")
    for group, values in tokens["bands"].items():
        out.append(f"        enum {group.capitalize()} {{")
        for key, value in values.items():
            out.append(f"            static let {key}: Double = {number(value)}")
        out.append("        }")
    out.append("    }")
    out.append("}")

    TARGET.write_text("\n".join(out) + "\n")
    print(f"wrote {TARGET.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
